/*
 * A032867  Numbers whose base-4 representation Sum_{i=0..m} d(i)*4^i has d(m)
 *          >= d(m-1) <= d(m-2) >= ...
 * https://oeis.org/A032867
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   compute numbers whose base-4 digits alternate in monotonicity:
 *            d(m) >= d(m-1) <= d(m-2) >= ... (zig‑zag). The sequence is
 *            generated by combinatorial enumeration of base-4 digits with
 *            this property
 * Range:     u8 n <= 113, u16 n <= 7899, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>

/* Count number of completions for a remaining length.
   rem  : how many digits are still to be placed after the current
   prev : the digit already placed (0..3)
   next_ge : true  => next digit must satisfy prev >= next
             false => prev <= next                                   */
static size_t cnt_rem[65][4][2];
static bool  cnt_vis[65][4][2] = { false };

/* Recursive helper with memoisation */
static size_t count_rec(size_t rem, int prev, bool next_ge)
{
    if (rem == 0) return 1;
    if (cnt_vis[rem][prev][next_ge]) return cnt_rem[rem][prev][next_ge];
    size_t total = 0;
    for (int d = 0; d < 4; ++d) {
        if ((next_ge && prev >= d) || (!next_ge && prev <= d))
            total += count_rec(rem - 1, d, !next_ge);
    }
    cnt_vis[rem][prev][next_ge] = true;
    cnt_rem[rem][prev][next_ge] = total;
    return total;
}

/* Main function required by the framework */
seq_t a(idx_t n)
{
    /* Handle invalid n (shouldn't happen in tests) */
    if (n == 0) return 0;

    /* Find the length of the number that holds the n-th term */
    size_t cumulative = 0;
    size_t len = 0;
    while (1) {
        ++len;
        size_t len_count = 0;
        for (int d0 = 1; d0 <= 3; ++d0) {
            len_count += count_rec(len - 1, d0, true);
        }
        if (cumulative + len_count >= n) break;
        cumulative += len_count;
    }

    size_t r = n - cumulative;   /* 1‑based position within this length */

    /* Build the number digit by digit (lexicographically) */
    seq_t  value   = 0;
    int    prev    = -1;          /* previous digit placed   */
    bool   next_ge = true;        /* next comparison direction */

    /* First digit (most‑significant) */
    for (int d0 = 1; d0 <= 3; ++d0) {
        size_t cnt = count_rec(len - 1, d0, true);
        if (r > cnt) {
            r -= cnt;
        } else {
            value = (seq_t)d0;
            prev  = d0;
            next_ge = true;        /* after first digit we need d0 >= d1 */
            break;
        }
    }

    /* Remaining digits */
    for (size_t pos = 1; pos < len; ++pos) {
        for (int d = 0; d < 4; ++d) {
            if ((next_ge && prev >= d) || (!next_ge && prev <= d)) {
                size_t cnt = count_rec(len - pos - 1, d, !next_ge);
                if (r > cnt) {
                    r -= cnt;
                } else {
                    value = value * 4 + (seq_t)d;
                    prev  = d;
                    next_ge = !next_ge;
                    break;
                }
            }
        }
    }

    return value;
}
